package com.example.appointment.adapter.in.rest;
import com.example.appointment.application.port.in.*; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import org.springframework.web.bind.annotation.*; import java.util.UUID;
@RestController @RequestMapping("/api/v1/integration/appointments") public class PartnerAppointmentCallbackController { private final ConfirmAppointmentUseCase confirm; private final CompleteAppointmentUseCase complete; public PartnerAppointmentCallbackController(ConfirmAppointmentUseCase c,CompleteAppointmentUseCase d){confirm=c;complete=d;} @PostMapping("/{id}/confirmed") public AppointmentController.AppointmentResponse confirmed(@PathVariable UUID id,@Valid @RequestBody ConfirmationRequest r){return AppointmentController.map(confirm.confirm(id,r.externalDmsReference));} @PostMapping("/{id}/completed") public AppointmentController.AppointmentResponse completed(@PathVariable UUID id,@RequestBody(required=false) CompletionRequest r){return AppointmentController.map(complete.complete(id,r==null?null:r.externalDmsReference));} record ConfirmationRequest(@NotBlank String externalDmsReference){} record CompletionRequest(String externalDmsReference){} }
